import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { responseMetadataSchema, type ResponseMetadata } from "./response-metadata.js";

export type SideBySideImplementation = {
  /** Unique identifier for this implementation variant. */
  implementationId?: string;
  /** Human-readable name for this implementation (e.g., "Variant A", "GPT-4", "Claude"). */
  implementationName?: string;
  /** The search/chat parameters used for this implementation. */
  searchParams?: Record<string, string>;
  /** The full response generated by this implementation. */
  response?: string;
  /** Metadata about the response (e.g., latency, token count). */
  responseMetadata?: ResponseMetadata;
};

export const sideBySideImplementationSchema: Schema<SideBySideImplementation> =
  s.object<SideBySideImplementation>({
    implementationId: s.optional(s.string()),
    implementationName: s.optional(s.string()),
    searchParams: s.optional(s.record(s.string(), s.string())),
    response: s.optional(s.string()),
    responseMetadata: s.optional(s.lazy(() => responseMetadataSchema)),
  });
